function o(t){if(t<1024)return`${t} B`;const e=["KB","MB","GB","TB"];let n=t/1024,r=0;for(;n>=1024&&r<e.length-1;)n/=1024,r++;return`${n.toFixed(1)} ${e[r]}`}function a(t){if(!t)return"never";const e=new Date(t).getTime();return Number.isNaN(e)?t:i((Date.now()-e)/1e3)}function i(t){if(t==null||Number.isNaN(t))return"never";if(t<0)return"just now";const e=[["day",86400],["hour",3600],["minute",60]];for(const[n,r]of e)if(t>=r){const u=Math.floor(t/r);return`${u} ${n}${u===1?"":"s"} ago`}return"just now"}function f(t){if(!t)return"—";const e=new Date(t);return Number.isNaN(e.getTime())?t:e.toLocaleString()}function m(t){if(t<1e3)return`${t} ms`;const e=t/1e3;return e<60?`${e.toFixed(1)} s`:`${Math.floor(e/60)}m ${Math.round(e%60)}s`}export{f as a,a as b,o as c,m as d,i as f};
